class MainActivity:ComponentActivity(){override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(arrayOf(Manifest.permission.POST_NOTIFICATIONS),1001);setContent{MaterialTheme{val cs=remember{CredentialStore(this)};AIQuotaScreen(remember{AccountStore(this)},cs,remember{UsageService(cs)},remember{OAuthManager(this)}){AIQuotaWidget().updateAll(this)}}}}}

@Composable private fun AIQuotaScreen(store:AccountStore,credentials:CredentialStore,service:UsageService,oauth:OAuthManager,updateWidget:suspend()->Unit){val scope=rememberCoroutineScope();val context=LocalContext.current;var accounts by remember{mutableStateOf(store.accounts())};var selected by remember{mutableStateOf(ProviderId.CODEX)};var name by remember{mutableStateOf("")};var access by remember{mutableStateOf("")};var refresh by remember{mutableStateOf("")};var accountId by remember{mutableStateOf("")};var paste by remember{mutableStateOf("")};var status by remember{mutableStateOf("")};var reauth by remember{mutableStateOf<String?>(null)}
fun reload(){accounts=store.accounts()};suspend fun refreshOne(a:AccountRecord){store.clearCooldown(a.id);runCatching{service.refresh(a)}.onSuccess{store.clearCooldown(a.id);store.saveSnapshot(it.copy(stale=false,errorMessage=null,errorKind=null))}.onFailure{store.markStale(a.id,it.message?:context.getString(R.string.health_unknown))}}
fun saveCredential(provider:ProviderId,c:Credential){val id=reauth;if(id!=null){accounts.firstOrNull{it.id==id}?.let{a->credentials.save(a.id,c);store.clearCooldown(a.id);reauth=null;name="";status=context.getString(R.string.reauth_success,a.name);scope.launch{withContext(Dispatchers.IO){refreshOne(a)};updateWidget();reload()};return};reauth=null};val a=AccountRecord(provider=provider,name=name.ifBlank{provider.name});store.upsert(a);credentials.save(a.id,c);name="";reload();scope.launch{updateWidget()}}
fun beginReauth(a:AccountRecord){selected=a.provider;reauth=a.id;name=a.name;paste="";status=if(a.provider==ProviderId.DEEPSEEK)context.getString(R.string.reauth_api_key,a.name)else context.getString(R.string.reauth_in_progress,a.name)};val recommended=recommendedAccountIds(accounts,store)
Scaffold{padding->LazyColumn(Modifier.fillMaxSize().padding(padding).padding(16.dp),verticalArrangement=Arrangement.spacedBy(10.dp)){
item{Text(stringResource(R.string.app_name),style=MaterialTheme.typography.headlineMedium);Text(stringResource(R.string.app_subtitle));Spacer(Modifier.height(8.dp));Row(horizontalArrangement=Arrangement.spacedBy(6.dp)){ProviderId.entries.forEach{p->TextButton(onClick={selected=p;paste="";reauth=null}){Text(if(selected==p)"● ${p.name}" else p.name)}}};if(reauth!=null){Text(stringResource(R.string.reauth_mode));TextButton(onClick={reauth=null;name="";paste="";status=context.getString(R.string.reauth_cancelled)}){Text(stringResource(R.string.cancel_reauth))}};OutlinedTextField(name,{name=it},label={Text(stringResource(R.string.account_name_optional))},modifier=Modifier.fillMaxWidth());when(selected){ProviderId.CODEX->{Button(onClick={status=context.getString(R.string.codex_open_browser);scope.launch{runCatching{oauth.loginCodex()}.onSuccess{saveCredential(ProviderId.CODEX,it)}.onFailure{status=context.getString(R.string.codex_manual_fallback,it.message?:"OAuth failed")}}}){Text(stringResource(if(reauth!=null)R.string.codex_relogin else R.string.codex_login))};OutlinedTextField(paste,{paste=it},label={Text(stringResource(R.string.codex_callback_hint))},modifier=Modifier.fillMaxWidth());Button(enabled=paste.isNotBlank(),onClick={scope.launch{runCatching{oauth.completeCodexManual(paste)}.onSuccess{saveCredential(ProviderId.CODEX,it);paste=""}.onFailure{status=it.message?:"Codex callback failed"}}}){Text(stringResource(R.string.codex_callback))}};ProviderId.CLAUDE->{Button(onClick={oauth.beginClaude();status=context.getString(R.string.claude_paste_code)}){Text(stringResource(if(reauth!=null)R.string.claude_relogin else R.string.claude_login))};OutlinedTextField(paste,{paste=it},label={Text(stringResource(R.string.claude_code_hint))},modifier=Modifier.fillMaxWidth());Button(enabled=paste.isNotBlank(),onClick={scope.launch{runCatching{oauth.completeClaude(paste)}.onSuccess{saveCredential(ProviderId.CLAUDE,it);paste=""}.onFailure{status=it.message?:"Claude OAuth failed"}}}){Text(stringResource(R.string.claude_complete))}};ProviderId.KIMI->Button(onClick={status=context.getString(R.string.kimi_starting);scope.launch{runCatching{oauth.loginKimi()}.onSuccess{saveCredential(ProviderId.KIMI,it)}.onFailure{status=it.message?:"Kimi OAuth failed"}}}){Text(stringResource(if(reauth!=null)R.string.kimi_relogin else R.string.kimi_login))};ProviderId.DEEPSEEK->Unit};Text(stringResource(R.string.oauth_fallback));OutlinedTextField(access,{access=it},label={Text(stringResource(if(selected==ProviderId.DEEPSEEK)R.string.api_key else R.string.access_token))},modifier=Modifier.fillMaxWidth());if(selected!=ProviderId.DEEPSEEK)OutlinedTextField(refresh,{refresh=it},label={Text(stringResource(R.string.refresh_token))},modifier=Modifier.fillMaxWidth());if(selected==ProviderId.CODEX)OutlinedTextField(accountId,{accountId=it},label={Text(stringResource(R.string.account_id_optional))},modifier=Modifier.fillMaxWidth());Button(enabled=access.isNotBlank(),onClick={saveCredential(selected,Credential(access.trim(),refresh.trim().ifBlank{null},accountId=accountId.trim().ifBlank{null}));access="";refresh="";accountId=""}){Text(stringResource(if(reauth!=null)R.string.update_credentials else R.string.import_credentials))};if(status.isNotBlank())Text(status);Spacer(Modifier.height(8.dp));Button(onClick={scope.launch{status=context.getString(R.string.refreshing);withContext(Dispatchers.IO){store.accounts().filter{it.enabled}.forEach{refreshOne(it)}};updateWidget();status=context.getString(R.string.refresh_complete);reload()}}){Text(stringResource(R.string.refresh_all))}}
items(accounts,key={it.id}){a->val snapshot=store.snapshot(a.id);val health=providerHealthText(context,snapshot,store.cooldownUntil(a.id));val credentialHealth=stringResource(credentialHealthRes(a,credentials,snapshot?.stale==true));val needs=snapshot?.errorKind==ProviderErrorKind.AUTHENTICATION||snapshot?.errorMessage?.let(ProviderErrorClassifier::classify)==ProviderErrorKind.AUTHENTICATION;Card(Modifier.fillMaxWidth()){Column(Modifier.padding(12.dp)){val rec=if(recommended.contains(a.id))" ★ ${stringResource(R.string.recommended)}" else "";val hidden=if(!a.enabled)" · ${stringResource(R.string.hidden)}" else "";Text("${a.provider.name} · ${a.name}$rec$hidden",style=MaterialTheme.typography.titleMedium);Text(stringResource(R.string.credential_status,credentialHealth));health?.let{Text(it)};val summary=snapshot?.balance?.let{"${it.symbol}${"%.2f".format(it.total)}"}?:snapshot?.windows?.joinToString("  "){w->val reset=w.resetAtEpochSeconds?.let(::formatCountdown);if(reset==null)"${w.label} ${w.remainingPercent.roundToInt()}%" else "${w.label} ${w.remainingPercent.roundToInt()}% ↻$reset"}?:stringResource(R.string.no_data);Text(summary);Row{TextButton(onClick={scope.launch{status="${context.getString(R.string.refresh)} ${a.name}…";withContext(Dispatchers.IO){refreshOne(a)};updateWidget();status=context.getString(R.string.refresh_complete);reload()}}){Text(stringResource(R.string.refresh))};TextButton(onClick={beginReauth(a)}){Text(if(needs)"⚠ ${stringResource(R.string.reauthenticate)}" else stringResource(R.string.reauthenticate))};TextButton(onClick={store.setEnabled(a.id,!a.enabled);reload();scope.launch{updateWidget()}}){Text(stringResource(if(a.enabled)R.string.hide else R.string.show))};TextButton(onClick={store.move(a.id,-1);reload();scope.launch{updateWidget()}}){Text("↑")};TextButton(onClick={store.move(a.id,1);reload();scope.launch{updateWidget()}}){Text("↓")};TextButton(onClick={store.delete(a.id);credentials.delete(a.id);reload();scope.launch{updateWidget()}}){Text(stringResource(R.string.delete))}}}}}
