private fun providerHealthText(context:android.content.Context,snapshot:UsageSnapshot?,cooldown:Long?):String?{snapshot?:return null;val kind=snapshot.errorKind?:snapshot.errorMessage?.let(ProviderErrorClassifier::classify)?:return null;val label=context.getString(when(kind){ProviderErrorKind.AUTHENTICATION->R.string.health_authentication;ProviderErrorKind.RATE_LIMITED->R.string.health_rate_limited;ProviderErrorKind.PROVIDER_UNAVAILABLE->R.string.health_provider_unavailable;ProviderErrorKind.NETWORK->R.string.health_network;ProviderErrorKind.INVALID_RESPONSE->R.string.health_invalid_response;ProviderErrorKind.CONFIGURATION->R.string.health_configuration;ProviderErrorKind.UNKNOWN->R.string.health_unknown});val icon=when(kind){ProviderErrorKind.AUTHENTICATION->"🔐";ProviderErrorKind.RATE_LIMITED->"⏳";ProviderErrorKind.PROVIDER_UNAVAILABLE->"☁";ProviderErrorKind.NETWORK->"⌁";ProviderErrorKind.INVALID_RESPONSE->"⚠";ProviderErrorKind.CONFIGURATION->"⚙";ProviderErrorKind.UNKNOWN->"⚠"};val base=if(snapshot.stale&&(snapshot.windows.isNotEmpty()||snapshot.balance!=null))context.getString(R.string.health_cached,label)else label;val retry=cooldown?.let{" · ${context.getString(R.string.health_retry_in,formatCountdown(it))}"}.orEmpty();return "$icon $base$retry"}
@StringRes private fun credentialHealthRes(a:AccountRecord,s:CredentialStore,stale:Boolean):Int{val c=s.get(a.id)?:return R.string.credential_sign_in_again;if(a.provider==ProviderId.DEEPSEEK)return if(stale)R.string.credential_cached else R.string.credential_healthy;val e=c.expiresAtEpochSeconds;if(e!=null){val now=System.currentTimeMillis()/1000;if(e<=now)return if(!c.refreshToken.isNullOrBlank())R.string.credential_refreshable else R.string.credential_sign_in_again;if(e-now<3600)return R.string.credential_renew_soon};return if(stale)R.string.credential_cached else R.string.credential_healthy}
private fun formatCountdown(epoch:Long):String{val r=(epoch-System.currentTimeMillis()/1000).coerceAtLeast(0);val d=r/86400;val h=(r%86400)/3600;val m=(r%3600)/60;return when{d>0->"${d}d ${h}h";h>0->"${h}h ${m}m";else->"${m.coerceAtLeast(1)}m"}}
private fun recommendedAccountIds(accounts:List<AccountRecord>,store:AccountStore):Set<String>=ProviderId.entries.mapNotNull{p->accounts.asSequence().filter{it.enabled&&it.provider==p}.mapNotNull{a->val s=store.snapshot(a.id)?.takeUnless{it.stale}?:return@mapNotNull null;val score=s.balance?.total?:s.windows.minOfOrNull{it.remainingPercent}?:return@mapNotNull null;a.id to score}.maxByOrNull{it.second}?.first}.toSet()
